package agent

import("context";"errors";"math";"strings";"sync";"time")
type Plan struct{ID string;RequestsPerDay int;TokensPerDay int64;MaxInputTokens int64;MaxOutputTokens int64}
var Plans=map[string]Plan{"free":{ID:"free",RequestsPerDay:20,TokensPerDay:20000,MaxInputTokens:4000,MaxOutputTokens:2000},"basic":{ID:"basic",RequestsPerDay:100,TokensPerDay:100000,MaxInputTokens:8000,MaxOutputTokens:4000},"standard":{ID:"standard",RequestsPerDay:500,TokensPerDay:500000,MaxInputTokens:16000,MaxOutputTokens:8000},"pro":{ID:"pro",RequestsPerDay:2000,TokensPerDay:2000000,MaxInputTokens:32000,MaxOutputTokens:16000}}
type Usage struct{Requests int;Tokens int64;ResetAt time.Time};type QuotaStore interface{Get(context.Context,Scope)(Usage,error);Put(context.Context,Scope,Usage)error};type QuotaGate struct{Store QuotaStore;mu sync.Mutex}
func(q *QuotaGate)CheckAndConsume(ctx context.Context,scope Scope,plan Plan,tokens int64)error{if q==nil||q.Store==nil{return errors.New("quota store is required")};if ctx==nil{return errors.New("context is required")};if err:=ctx.Err();err!=nil{return err};plan.ID=strings.TrimSpace(plan.ID);if plan.ID==""||plan.RequestsPerDay<=0||plan.TokensPerDay<=0||plan.MaxInputTokens<=0||plan.MaxOutputTokens<=0||tokens<0{return errors.New("invalid quota")};if tokens>plan.MaxInputTokens+plan.MaxOutputTokens{return errors.New("request exceeds token limits")};if tokens>plan.TokensPerDay{return errors.New("request exceeds token quota")};if strings.TrimSpace(scope.TenantID)==""||len(strings.TrimSpace(scope.TenantID))>256{return errors.New("invalid tenant scope")};q.mu.Lock();defer q.mu.Unlock();u,err:=q.Store.Get(ctx,scope);if err!=nil{return err};now:=time.Now().UTC();if u.ResetAt.IsZero()||!now.Before(u.ResetAt){u=Usage{ResetAt:now.Add(24*time.Hour)}};if u.Requests<0||u.Tokens<0{return errors.New("invalid stored usage")};if u.Requests>=plan.RequestsPerDay||u.Tokens>plan.TokensPerDay-tokens{return errors.New("AI usage quota exceeded")};if u.Tokens>math.MaxInt64-tokens{return errors.New("usage counter overflow")};u.Requests++;u.Tokens+=tokens;return q.Store.Put(ctx,scope,u)}
